export const SNR_THRESHOLDS = {
  GOOD: 15,    // dB
  MEDIUM: 5,   // dB
  POOR: 0      // dB
};

export function snrColor(snr: number): string {
  if (snr >= SNR_THRESHOLDS.GOOD) return '#008855';
  if (snr >= SNR_THRESHOLDS.MEDIUM) return '#c89000';
  return '#cc2233';
}

export function elevationColor(elev: number): string {
  if (elev >= 60) return '#008855';
  if (elev >= 30) return '#c89000';
  if (elev >= 10) return '#e07030';
  return '#cc2233';
}

export function stateColor(state: string): string {
  switch (state) {
    case 'ACTIVE': return '#008855';
    case 'AUTONOMOUS': return '#e07030';
    case 'FEEDER_OUTAGE': return '#cc2233';
    case 'ECLIPSE': return '#7b4fcf';
    case 'SYNCING': return '#0099cc';
    default: return '#888888';
  }
}

