export function getPreset(name: keyof typeof SIM_PRESETS): SimConfig {
  return { ...SIM_PRESETS[name] };
}

export function mergeConfig(base: SimConfig, override: Partial<SimConfig>): SimConfig {
  return { ...base, ...override };
}