/**
 * airan-ntn — CLI Entry Point
 * Headless batch simulation runs
 */

import { AiranNtnSimulator } from './simulator.js';
import { SimConfig, DEFAULT_CONFIG, RoundMetrics } from './types.js';
import { SIM_PRESETS } from './config.js';
import { writeFileSync } from 'fs';
import { resolve } from 'path';
import { fileURLToPath } from 'url';
import { dirname } from 'path';

// Handle both ESM and CJS
const __filename = typeof import.meta !== 'undefined' && import.meta.url
  ? fileURLToPath(import.meta.url)
  : process.argv[1];
const __dirname = dirname(__filename);

// ──────────────────────────────────────────────────────────────────────────────
// CLI Argument Parsing
// ──────────────────────────────────────────────────────────────────────────────

interface CliArgs {
  preset?: keyof typeof SIM_PRESETS;
  config?: string;
  output?: string;
  rounds?: number;
  ues?: number;
  orbitals?: number;
  planes?: number;
  seed?: number;
  quiet?: boolean;
  csv?: boolean;
  json?: boolean;
}

function parseArgs(): CliArgs {
  const args: CliArgs = {};
  const argv = process.argv.slice(2);

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    const next = argv[i + 1];

    switch (arg) {
      case '--preset':
      case '-p':
        args.preset = next as keyof typeof SIM_PRESETS;
        i++;
        break;
      case '--config':
      case '-c':
        args.config = next;
        i++;
        break;
      case '--output':
      case '-o':
        args.output = next;
        i++;
        break;
      case '--rounds':
      case '-r':
        args.rounds = parseInt(next, 10);
        i++;
        break;
      case '--ues':
      case '-u':
        args.ues = parseInt(next, 10);
        i++;
        break;
      case '--orbitals':
        args.orbitals = parseInt(next, 10);
        i++;
        break;
      case '--planes':
        args.planes = parseInt(next, 10);
        i++;
        break;
      case '--seed':
        args.seed = parseInt(next, 10);
        i++;
        break;
      case '--quiet':
      case '-q':
        args.quiet = true;
        break;
      case '--csv':
        args.csv = true;
        break;
      case '--json':
        args.json = true;
        break;
      case '--help':
      case '-h':
        printHelp();
        process.exit(0);
    }
  }

  return args;
}

function printHelp(): void {
  console.log(`
airan-ntn — O-RAN NTN Simulator CLI

Usage: airan-ntn [options]

Options:
  -p, --preset <name>     Preset configuration (demo, standard, large, geo, fl_focused)
  -c, --config <file>     Load JSON config file
  -o, --output <file>     Output file for results
  -r, --rounds <n>        Total FL rounds
  -u, --ues <n>           Number of UEs
  --orbitals <n>          Satellites per orbital plane
  --planes <n>            Number of orbital planes
  --seed <n>              Random seed
  -q, --quiet             Suppress progress output
  --csv                   Output CSV to stdout
  --json                  Output JSON to stdout
  -h, --help              Show this help

Presets:
  demo           Quick demo (6×3 sats, 10 UEs, 20 rounds)
  standard       Starlink-like (12×6 sats, 20 UEs, 50 rounds)
  large          Full constellation (22×6 sats, 50 UEs, 100 rounds)
  geo            3 GEO satellites (1×3 sats, 15 UEs, 30 rounds)
  fl_focused     FL-heavy (8×4 sats, 40 UEs, 100 rounds)

Examples:
  airan-ntn --preset standard --rounds 100 --output results.json
  airan-ntn -p demo --csv > rounds.csv
  airan-ntn --config myconfig.json --json
`);
}

// ──────────────────────────────────────────────────────────────────────────────
// Build Config from Args
// ──────────────────────────────────────────────────────────────────────────────

async function buildConfig(args: CliArgs): Promise<SimConfig> {
  let config: SimConfig = { ...DEFAULT_CONFIG };

  // Apply preset
  if (args.preset && SIM_PRESETS[args.preset]) {
    config = { ...config, ...SIM_PRESETS[args.preset] };
  }

  // Apply config file
  if (args.config) {
    try {
      const { readFileSync } = await import('fs');
      const fileConfig = JSON.parse(readFileSync(args.config, 'utf-8'));
      config = { ...config, ...fileConfig };
    } catch (e) {
      console.error(`Failed to load config: ${e}`);
      process.exit(1);
    }
  }

  // Apply CLI overrides
  if (args.rounds !== undefined) config.totalRounds = args.rounds;
  if (args.ues !== undefined) config.numUEs = args.ues;
  if (args.orbitals !== undefined) config.numOrbitals = args.orbitals;
  if (args.planes !== undefined) config.numPlanes = args.planes;
  if (args.seed !== undefined) config.seed = args.seed;

  return config;
}

// ──────────────────────────────────────────────────────────────────────────────
// Progress Callback
// ──────────────────────────────────────────────────────────────────────────────

function createProgressCallback(quiet: boolean): (m: RoundMetrics) => void {
  let lastLog = 0;
  return (m: RoundMetrics) => {
    if (quiet) return;
    const now = Date.now();
    if (now - lastLog > 1000 || m.round === 1) {
      console.log(`Round ${m.round}: Loss=${m.globalLoss.toFixed(4)}, Acc=${(m.globalAccuracy*100).toFixed(1)}%, SNR=${m.avgSNR.toFixed(1)}dB, Feeder=${(m.feederLinkUptime*100).toFixed(0)}%`);
      lastLog = now;
    }
  };
}

// ──────────────────────────────────────────────────────────────────────────────
// Main
// ──────────────────────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  const args = parseArgs();
  const config = await buildConfig(args);

  if (!args.quiet) {
    console.log('airan-ntn simulator starting...');
    console.log(`Config: ${config.numOrbitals}×${config.numPlanes} sats, ${config.numUEs} UEs, ${config.totalRounds} rounds`);
    console.log(`FL: ${config.flAlgorithm}/${config.scheduler}, Seed: ${config.seed}`);
  }

  const sim = new AiranNtnSimulator(config);
  const onRound = createProgressCallback(args.quiet ?? false);

  const startTime = Date.now();
  const history = sim.runAll(onRound);
  const elapsed = Date.now() - startTime;

  if (!args.quiet) {
    console.log(`\nCompleted in ${(elapsed / 1000).toFixed(1)}s`);
    const final = history[history.length - 1];
    console.log(`Final: Loss=${final.globalLoss.toFixed(4)}, Acc=${(final.globalAccuracy*100).toFixed(1)}%`);
    console.log(`Avg SNR: ${final.avgSNR.toFixed(1)}dB, Feeder uptime: ${(final.feederLinkUptime*100).toFixed(1)}%`);
    console.log(`Handovers: ${final.handovers}, Sat energy: ${final.satelliteEnergy.toFixed(1)} Wh`);
  }

  // Output results
  const output = {
    config,
    history,
    summary: {
      totalRounds: history.length,
      finalLoss: history[history.length - 1]?.globalLoss ?? 0,
      finalAccuracy: history[history.length - 1]?.globalAccuracy ?? 0,
      avgSNR: history.reduce((a, b) => a + b.avgSNR, 0) / history.length,
      avgFeederUptime: history.reduce((a, b) => a + b.feederLinkUptime, 0) / history.length,
      totalHandovers: history[history.length - 1]?.handovers ?? 0,
      elapsedMs: elapsed
    }
  };

  if (args.json) {
    console.log(JSON.stringify(output, null, 2));
  } else if (args.csv) {
    const headers = ['round', 'loss', 'accuracy', 'avgSNR', 'minSNR', 'participation', 'commBits', 'avgElev', 'avgDoppler', 'feederUptime', 'handovers', 'satEnergy'];
    const rows = history.map(m => [
      m.round, m.globalLoss, m.globalAccuracy, m.avgSNR, m.minSNR,
      m.participationRate, m.commCostBits, m.avgElevation, m.avgDoppler,
      m.feederLinkUptime, m.handovers, m.satelliteEnergy
    ]);
    const csv = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    console.log(csv);
  } else if (args.output) {
    writeFileSync(resolve(args.output), JSON.stringify(output, null, 2));
    console.log(`Results written to ${args.output}`);
  }
}

main().catch(e => {
  console.error('Error:', e);
  process.exit(1);
});