/**
 * airan-ntn — NTN-Aware Scheduler
 * UE selection considering elevation, Doppler, feeder link status, satellite energy
 */

import { Scheduler, SchedulerType, SimConfig, UserEquipment, Satellite } from '../types.js';
import { vec3Len, vec3Sub } from '../types.js';
import { calculateElevation } from '../orbital.js';

// ──────────────────────────────────────────────────────────────────────────────
// Standard Schedulers (from Wireless-Decentralized-FL)
// ──────────────────────────────────────────────────────────────────────────────

export class RandomScheduler implements Scheduler {
  readonly name = 'Random' as const;
  select(ues: UserEquipment[], k: number): UserEquipment[] {
    const available = ues.filter(u => u.dataSize > 0);
    const shuffled = [...available].sort(() => Math.random() - 0.5);
    return shuffled.slice(0, Math.min(k, available.length));
  }
  reset(): void {}
}

export class RoundRobinScheduler implements Scheduler {
  readonly name = 'RoundRobin' as const;
  private pointer = 0;
  select(ues: UserEquipment[], k: number): UserEquipment[] {
    const available = ues.filter(u => u.dataSize > 0).sort((a, b) => a.id - b.id);
    if (available.length === 0) return [];
    const selected: UserEquipment[] = [];
    for (let i = 0; i < k && selected.length < available.length; i++) {
      const idx = (this.pointer + i) % available.length;
      selected.push(available[idx]);
    }
    this.pointer = (this.pointer + k) % available.length;
    return selected;
  }
  reset(): void { this.pointer = 0; }
}

export class MaxMinScheduler implements Scheduler {
  readonly name = 'MaxMin' as const;
  select(ues: UserEquipment[], k: number): UserEquipment[] {
    const available = ues.filter(u => u.dataSize > 0);
    available.sort((a, b) => b.snr - a.snr);
    return available.slice(0, Math.min(k, available.length));
  }
  reset(): void {}
}

